\fill (P) circle (1.6pt);
\pic[draw, blue, "$\theta$", angle radius=1.35cm, angle eccentricity=1.55] {angle=X--O--P};
\pic[draw, red, "$A$", angle radius=0.65cm, angle eccentricity=2.3] {angle=P--O--Xn};
\node[anchor=west] at (-3.1,3.5) {Quadrant 2};
